package com.portfolio.features.education.dto; import jakarta.validation.constraints.*; import java.time.LocalDate; public record EducationRequest(@NotBlank(message="School is required.") String school,String degree,String major,LocalDate startDate,LocalDate endDate,String description,int sortOrder){@AssertTrue(message="End date must be after start date.") public boolean validDates(){return startDate==null||endDate==null||!endDate.isBefore(startDate);}}
